def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Validate inputs
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")
    if not isinstance(level, int):
        raise TypeError("level must be an integer")
    # Normalize level: treat any negative value other than -1 as infinite
    if level < -1:
        level = -1

    try:
        result = {}
        for key, val1 in d1.items():
            if key not in d2:
                # Key only in d1
                result[key] = val1
            else:
                val2 = d2[key]
                if val1 == val2:
                    # Same value, skip
                    continue
                # Values differ
                if isinstance(val1, dict) and isinstance(val2, dict):
                    # Both are dicts: recurse if allowed
                    if level == 0:
                        # No recursion allowed at this depth
                        result[key] = val1
                    else:
                        sublevel = level - 1 if level > 0 else -1
                        subdiff = difference(val1, val2, sublevel)
                        if subdiff:
                            result[key] = subdiff
                else:
                    # At least one value is not a dict; include val1
                    result[key] = val1
        return result
    except RecursionError as e:
        raise RuntimeError("Maximum recursion depth exceeded while computing difference") from e
    except Exception as e:
        # Re-raise any other exception with context
        raise RuntimeError(f"Error computing difference: {e}") from e

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    if weight is None:
        weight = 1
    try:
        weight = np.asarray(weight)
    except Exception as exc:
        raise ValueError("weight must be numeric or array-like") from exc

    # Validate coordinate
    try:
        coord = np.asarray(coord)
    except Exception as exc:
        raise ValueError("coord must be array-like") from exc
    if coord.ndim != 1:
        raise ValueError("coord must be a 1-D array")

    # Retrieve edges
    if not hasattr(self, "edges"):
        raise AttributeError("Histogram object has no 'edges' attribute")
    edges = self.edges
    if isinstance(edges, np.ndarray):
        edges = [edges]
    else:
        try:
            edges = [np.asarray(e) for e in edges]
        except Exception as exc:
            raise ValueError("Each edge must be array-like") from exc

    if len(coord) != len(edges):
        raise ValueError("coord length does not match histogram dimensions")

    # Find bin indices
    idx = []
    for c, e in zip(coord, edges):
        if e.ndim != 1:
            raise ValueError("Each edge array must be 1-D")
        if len(e) < 2:
            raise ValueError("Edge array must contain at least two edges")
        bin_idx = np.searchsorted(e, c, side="right") - 1
        if bin_idx < 0 or bin_idx >= len(e) - 1:
            # Outside the histogram bounds; ignore
            return
        idx.append(bin_idx)

    # Increment the appropriate bin
    if not hasattr(self, "bins"):
        raise AttributeError("Histogram object has no 'bins' attribute")
    try:
        self.bins[tuple(idx)] += weight
    except Exception as exc:
        raise RuntimeError("Failed to increment histogram bin") from exc

