def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of inputs
    if not isinstance(subcommand, str):
        raise TypeError("subcommand must be a string")
    if not isinstance(type_name, str):
        raise TypeError("type_name must be a string")
    if not isinstance(option_name, str):
        raise TypeError("option_name must be a string")
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dict")

    # Helper function that will be used as the argparse type
    def _complex_type(value):
        """Parse a complex argument according to spec_option."""
        # If a split character is specified, split the value
        split_char = spec_option.get("split")
        if split_char is not None:
            parts = value.split(split_char)
            expected = spec_option.get("expected_parts")
            if expected is not None and len(parts) != expected:
                raise ValueError(
                    f"{option_name} expects {expected} parts separated by "
                    f"'{split_char}', got {len(parts)}: {value}"
                )
            # Optionally convert each part
            convert = spec_option.get("convert")
            if convert is not None and callable(convert):
                try:
                    parts = [convert(p) for p in parts]
                except Exception as exc:
                    raise ValueError(
                        f"Error converting parts of {option_name}: {exc}"
                    ) from exc
            return parts

        # If a regex pattern is provided, validate the value
        pattern = spec_option.get("regex")
        if pattern is not None:
            import re
            if not re.match(pattern, value):
                raise ValueError(
                    f"{option_name} value '{value}' does not match pattern "
                    f"'{pattern}'"
                )
            # Optionally capture groups
            groups = spec_option.get("groups")
            if groups:
                match = re.match(pattern, value)
                return match.groupdict() if groups == "dict" else match.groups()

        # If a custom parser function is provided, use it
        parser = spec_option.get("parser")
        if parser is not None and callable(parser):
            try:
                return parser(value)
            except Exception as exc:
                raise ValueError(
                    f"Custom parser for {option_name} raised an error: {exc}"
                ) from exc

        # Default: return the raw value
        return value

    # Attach metadata to the function for debugging / introspection
    _complex_type.__name__ = f"{type_name}_{subcommand}"
    _complex_type.__doc__ = (
        f"Complex type for option '{option_name}' in subcommand '{subcommand}'. "
        f"Specification: {spec_option}"
    )
    return _complex_type

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary, got %r" % type(args).__name__)

    control_args = {}
    nested_args = {}

    for key, value in args.items():
        # Treat keys starting with 'control_' as control arguments.
        if isinstance(key, str) and key.startswith("control_"):
            control_args[key] = value
        else:
            # All other keys are considered nested (including custom vars).
            nested_args[key] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars (each should be a dict)
    :return: The updated dictionary
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return vars_dict
    if not isinstance(extra_vars, list):
        raise TypeError("extra_vars must be a list or None")
    for ev in extra_vars:
        if isinstance(ev, dict):
            vars_dict.update(ev)
        else:
            # Skip non-dict entries to avoid errors
            continue
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import os
    import json
    import subprocess
    import logging

    logger = logging.getLogger(__name__)

    # Validate playbook path
    if not os.path.isabs(playbook_path):
        playbook_path = os.path.abspath(playbook_path)
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Base command
    cmd = ["ansible-playbook", playbook_path]

    # Verbosity
    if verbose is not None:
        if isinstance(verbose, int) and verbose > 0:
            cmd.append("-" + "v" * verbose)
        elif isinstance(verbose, str):
            # Accept strings like "-v" or "-vv"
            cmd.append(verbose)
    else:
        # Default verbosity
        cmd.append("-v")

    # Extra vars
    if extra_vars:
        try:
            # Convert dict to JSON string for ansible
            json_vars = json.dumps(extra_vars)
            cmd.extend(["--extra-vars", json_vars])
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Invalid extra_vars: {exc}") from exc

    # Additional ansible arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    cmd.append(f"--{key}")
            else:
                cmd.append(f"--{key}={value}")

    logger.debug("Executing ansible-playbook command: %s", " ".join(cmd))

    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
            env=os.environ.copy()
        )
    except Exception as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook: {exc}") from exc

    if result.returncode != 0:
        error_msg = (
            f"ansible-playbook exited with code {result.returncode}\n"
            f"stdout:\n{result.stdout}\n"
            f"stderr:\n{result.stderr}"
        )
        raise RuntimeError(error_msg)

    return result.stdout.strip()

